#define STM32H735G_DK_BSP_VERSION_SUB1   (uint32_t)(0x02) /*!< [23:16] sub1 version */
#define STM32H735G_DK_BSP_VERSION_SUB2   (uint32_t)(0x03) /*!< [15:8]  sub2 version */
