#define STM32H735G_DK_BSP_VERSION        ((STM32H735G_DK_BSP_VERSION_MAIN << 24)\
                                          |(STM32H735G_DK_BSP_VERSION_SUB1 << 16)\
                                          |(STM32H735G_DK_BSP_VERSION_SUB2 << 8 )\
