    else if (MX25LM51245G_AutoPollingMemReady(&hospi_nor[Instance], Ospi_Nor_Ctx[Instance].InterfaceMode,
                                              Ospi_Nor_Ctx[Instance].TransferRate) != MX25LM51245G_OK)
    {
